arbs_g":0.0}},"contribution":{"kcal":0.0,"protein_g":0.0,"fat_g":0.0,"carbs_g":0.0}}],"unrounded_totals":{"kcal":85.17,"protein_g":2.8095000000000003,"fat_g":5.1105,"carbs_g":9.130799999999999},"optional_ingredients_included":false}}},"ingredients":[{"id":"007b4502-9554-41f8-bbf8-260c28c19d4f","name":"蠔油","note":null,"slug":"oyster-sauce","unit":"tsp","optional":false,"quantity":1.5},{"id":"c7cb9474-02fd-4c2d-b9f7-4086dc324b90","name":"糖","note":"平衡味道","slug":"sugar","unit":"tsp","optional":true,"quantity":0.25},{"id":"a172d728-35aa-4438-8cf0-6fc0177fb5aa","name":"冬菇","note":"鮮冬菇去硬蒂後淨重，並非乾冬菇","slug":"shiitake-mushroom","unit":"g","optional":false,"quantity":120},{"id":"57566777-1e27-447c-8b27-3f6788748add","name":"生抽","note":"可提味","slug":"soy-sauce","unit":"tbsp","optional":true,"quantity":0.16666666666666666},{"id":"5cc1bc35-5b7e-459a-9ca9-180242f03d44","name":"食油","note":null,"slug":"cooking-oil","unit":"tbsp","optional":false,"quantity":0.3333333333333333},{"id":"fb55e302-be78-46d6-9ca6-9ed8c4529567","name":"水","note":"炆煮用","slug":"water","unit":"ml","optional":false,"quantity":60}]}}]$payload$::jsonb) LOOP
 SELECT id INTO STRICT rid FROM public.recipes WHERE slug=p->>'slug' AND is_public;
 SELECT to_jsonb(r) INTO actual FROM public.recipes r WHERE id=rid;
 IF EXISTS(SELECT 1 FROM jsonb_each(p->'before'->'recipe') e WHERE actual->e.key IS DISTINCT FROM e.value) THEN
  RAISE EXCEPTION 'Recipe precondition changed: %',p->>'slug'; END IF;
 SELECT count(*) INTO n FROM public.recipe_ingredients WHERE recipe_id=rid;
 IF n<>jsonb_array_length(p->'before'->'ingredients') THEN RAISE EXCEPTION 'Ingredient count changed: %',p->>'slug'; END IF;
 FOR oldrow IN SELECT value FROM jsonb_array_elements(p->'before'->'ingredients') LOOP
  SELECT jsonb_build_object('slug',i.slug,'quantity',ri.quantity,'unit',u.code,'optional',ri.is_optional,'note',ri.prep_note) INTO actual
  FROM public.recipe_ingredients ri JOIN public.ingredients i ON i.id=ri.ingredient_id JOIN public.units u ON u.id=ri.unit_id
  WHERE ri.id=(oldrow->>'id')::uuid AND ri.recipe_id=rid;
  IF actual IS NULL OR actual-'quantity' IS DISTINCT FROM oldrow-'id'-'name'-'quantity' OR abs((actual->>'quantity')::numeric-(oldrow->>'quantity')::numeric)>0.000000000001 THEN RAISE EXCEPTION 'Ingredient precondition changed: %',p->>'slug'; END IF;
 END LOOP;
 SELECT count(*) INTO n FROM public.recipe_steps WHERE recipe_id=rid;
 IF n<>jsonb_array_length(p->'before'->'steps') THEN RAISE EXCEPTION 'Step count changed: %',p->>'slug'; END IF;
 FOR oldrow IN SELECT value FROM jsonb_array_elements(p->'before'->'steps') LOOP
  IF NOT EXISTS(SELECT 1 FROM public.recipe_steps WHERE id=(oldrow->>'id')::uuid AND recipe_id=rid AND text=oldrow->>'text') THEN RAISE EXCEPTION 'Step precondition changed: %',p->>'slug'; END IF;
 END LOOP;
 FOR v IN SELECT value FROM jsonb_array_elements(p->'after'->'ingredients') LOOP
  IF v->>'id' IS NULL THEN
   INSERT INTO public.recipe_ingredients(recipe_id,ingredient_id,quantity,unit_id,is_optional,prep_note)
   SELECT rid,i.id,(v->>'quantity')::numeric,u.id,(v->>'optional')::boolean,v->>'note' FROM public.ingredients i CROSS JOIN public.units u WHERE i.slug=v->>'slug' AND i.is_active AND u.code=v->>'unit';
  ELSE
   UPDATE public.recipe_ingredients ri SET ingredient_id=i.id,quantity=(v->>'quantity')::numeric,unit_id=u.id,is_optional=(v->>'optional')::boolean,prep_note=v->>'note'
   FROM public.ingredients i CROSS JOIN public.units u WHERE ri.id=(v->>'id')::uuid AND ri.recipe_id=rid AND i.slug=v->>'slug' AND i.is_active AND u.code=v->>'unit';
  END IF;
  GET DIAGNOSTICS n=ROW_COUNT;
  IF n<>1 THEN RAISE EXCEPTION 'Ingredient target missing: % / %',p->>'slug',v->>'slug'; END IF;
 END LOOP;
 FOR v IN SELECT value FROM jsonb_array_elements(p->'after'->'steps') LOOP
  UPDATE public.recipe_steps SET text=v->>'text' WHERE id=(v->>'id')::uuid AND recipe_id=rid;
 END LOOP;
 v=p->'after'->'recipe';
 UPDATE public.recipes SET name=v->>'name',description=v->>'description',calories_per_serving=(v->>'calories_per_serving')::integer,
 protein_g=(v->>'protein_g')::numeric,carbs_g=(v->>'carbs_g')::numeric,fat_g=(v->>'fat_g')::numeric,
 diet=ARRAY(SELECT jsonb_array_elements_text(v->'diet')),flavor=ARRAY(SELECT jsonb_array_elements_text(v->'flavor')),protein=ARRAY(SELECT jsonb_array_elements_text(v->'protein')),
 primary_protein=v->>'primary_protein',source_data=v->'source_data',updated_at=now() WHERE id=rid;
END LOOP;
END $repair$;
